slices.raw_text:
    host-name r-junos;
    services {
        ssh;
    }
}
interfaces {
    ge-0/0/0 {
        unit 0 {
            family inet { address 10.0.2.1/30; }
        }
    }
}
protocols {
    ospf {
        area 0.0.0.0 { interface ge-0/0/0.0; }
    }
}
routing-options {
    router-id 10.0.2.1;
}
daemon TerminAttr
   exec /usr/bin/TerminAttr -ingestgrpcurl=127.0.0.1:9910
   no shutdown
!
